import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>

// Fused kernel: out = sigmoid( tanh( x * scale ) * bias )
__global__ void fused_forward_kernel(const float* __restrict__ input,
                                     const float* __restrict__ scale,
                                     const float* __restrict__ bias,
                                     float* __restrict__ output,
                                     int N, int C, int D, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int size = N * C * D * H * W;
    if (idx < size) {
        int c_size = D * H * W;
        int n_c_size = C * c_size;
        int c = (idx % n_c_size) / c_size;

        float val = input[idx] * scale[c];
        val = tanhf(val);
        val = val * bias[c];
        val = 1.0f / (1.0f + expf(-val));
        output[idx] = val;
    }
}

torch::Tensor fused_forward(torch::Tensor input,
                            torch::Tensor scale,
                            torch::Tensor bias) {
    auto output = torch::empty_like(input);

    int N = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    int size = N * C * D * H * W;
    const int block = 256;
    const int grid = (size + block - 1) / block;

    fused_forward_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        scale.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D, H, W
    );

    return output;
}
''';

fused_cpp_source = r'''
torch::Tensor fused_forward(torch::Tensor input,
                            torch::Tensor scale,
                            torch::Tensor bias);
'''

fused_module = load_inline(
    name="fused_ops",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_source,
    functions=["fused_forward"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Model that performs a 3D convolution, then a fused custom CUDA op that does:
    x = sigmoid( tanh( x * scaling_factor ) * bias ).
    """
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor, bias_shape):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.scaling_factor = nn.Parameter(torch.randn(bias_shape))
        self.bias = nn.Parameter(torch.randn(bias_shape))

    def forward(self, x):
        x = self.conv(x)
        x = fused_module.fused_forward(x, self.scaling_factor, self.bias)
        return x

